//go:build amd64

#include "textflag.h"
#include "simd_amd64.h"
#include "loop_amd64.h"

// func _ShiftBlocks(dst, src []byte, free, used uint8)
//
// Writes dst[i] = src[i]<<free | src[i+1]>>used for every byte of dst, in
// blocks of 32. This is the same kernel lib/bitbuffer runs, written with the
// macros above rather than generated by avo.
TEXT ·_ShiftBlocks(SB), NOSPLIT, $0-50
	MOVQ    dst_base+0(FP), AX
	MOVQ    dst_len+8(FP), DX
	MOVQ    src_base+24(FP), BX
	MOVBLZX free+48(FP), SI
	MOVBLZX used+49(FP), DI

	// Y0 = broadcast(0xFF << free), the mask BYTE_SHL needs.
	MOVL $0x000000ff, R8
	MOVL SI, CX
	SHLL CL, R8
	ANDL $0x000000ff, R8
	BROADCAST_BYTE(R8, X1, Y0)

	// Y1 = broadcast(0xFF >> used), the mask BYTE_SHR needs.
	MOVL $0x000000ff, R8
	MOVL DI, CX
	SHRL CL, R8
	BROADCAST_BYTE(R8, X1, Y1)

	// The shift counts live in XMM for the whole loop, moved there once.
	VMOVD SI, X2
	VMOVD DI, X3
	XORQ  CX, CX

	LOOP_BEGIN(block, block_done, CX, DX)
	VMOVDQU (BX)(CX*1), Y4
	VMOVDQU 1(BX)(CX*1), Y5
	BYTE_SHL(X2, Y0, Y4)
	BYTE_SHR(X3, Y1, Y5)
	VPOR    Y5, Y4, Y4
	VMOVDQU Y4, (AX)(CX*1)
	LOOP_END(block, block_done, CX, $32)

	RET_VEC
